data_model:
CREATE TABLE employees (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, last_name VARCHAR(60) NOT NULL, first_name VARCHAR(60) NOT NULL, hire_date DATE NOT NULL, birth_month TINYINT UNSIGNED NULL, birth_day TINYINT UNSIGNED NULL, birth_year SMALLINT UNSIGNED NULL, status ENUM('active','departed') NOT NULL DEFAULT 'active', departed_on DATE NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, UNIQUE KEY uq_name (last_name, first_name)) ENGINE=InnoDB;  -- calendar titles use CONCAT(last_name,', ',first_name) so 'Walker, Rebecca - Vacation' titles stay identical. Birthday stored as month/day with OPTIONAL year because 12 of 15 current years are placeholders. Departure: status='departed' + departed_on hides the person from pickers and balances (toggle 'show former'), stops birthday generation, removes their future calendar events after departed_on, and KEEPS all past rows and past calendar events (today deleting a sheet row erases history).

CREATE TABLE time_off (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, employee_id INT UNSIGNED NOT NULL, type ENUM('pto','vacation') NOT NULL, start_date DATE NOT NULL, end_date DATE NOT NULL, note VARCHAR(200) NULL, created_by INT UNSIGNED NULL, created_at DATETIME NOT NULL, updated_by INT UNSIGNED NULL, updated_at DATETIME NOT NULL, deleted_at DATETIME NULL, KEY ix_emp_start (employee_id, start_date), KEY ix_start (start_date), FOREIGN KEY (employee_id) REFERENCES employees(id), CHECK (end_date >= start_date));  -- type stored lowercase (fixes the Vacation/vacation casing); working days are NOT stored, always computed; soft delete so calendar sync can retire the event and audit keeps history.

CREATE TABLE adjustments (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, employee_id INT UNSIGNED NOT NULL, type ENUM('pto','vacation') NOT NULL, effective_date DATE NOT NULL, days DECIMAL(4,1) NOT NULL, reason VARCHAR(200) NOT NULL, created_by INT UNSIGNED, created_at DATETIME NOT NULL, deleted_at DATETIME NULL, KEY (employee_id, effective_date));  -- the never-created 'PTO Adjustments' sheet, same semantics: effective_date picks the cycle, fractional allowed, + grant / - deduct.

CREATE TABLE calendars (cal_key VARCHAR(20) PRIMARY KEY, name VARCHAR(60), google_calendar_id VARCHAR(120), color CHAR(7), sync_enabled TINYINT(1) DEFAULT 1, sort_order INT);  -- seeded: timeoff, birthdays, company ('Any Additional Events'), factory, sales (End Of Month Sale; sync_enabled=0 after cutover if he agrees).

CREATE TABLE events (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, cal_key VARCHAR(20) NOT NULL, title VARCHAR(150) NOT NULL, start_date DATE NOT NULL, end_date DATE NOT NULL, created_by INT UNSIGNED, created_at DATETIME, updated_at DATETIME, deleted_at DATETIME NULL, KEY (cal_key, start_date), FOREIGN KEY (cal_key) REFERENCES calendars(cal_key));  -- replaces the three event sheets.

CREATE TABLE calendar_mirror (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, cal_key VARCHAR(20) NOT NULL, source ENUM('time_off','birthday','event') NOT NULL, source_id INT UNSIGNED NOT NULL, source_year SMALLINT NULL, google_event_id VARCHAR(100) NULL, title VARCHAR(200), start_date DATE, end_date DATE, fingerprint CHAR(40), state ENUM('pending','synced','delete_pending','error') NOT NULL, attempts TINYINT DEFAULT 0, last_error VARCHAR(500) NULL, synced_at DATETIME NULL, UNIQUE KEY uq_src (source, source_id, source_year));  -- one row per Google event the app owns.

CREATE TABLE users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, employee_id INT UNSIGNED NULL UNIQUE, email VARCHAR(120) NOT NULL UNIQUE, name VARCHAR(100), role ENUM('admin','staff') NOT NULL DEFAULT 'staff', password_hash VARCHAR(255) NULL, invite_token_hash CHAR(64) NULL, invite_expires_at DATETIME NULL, is_active TINYINT(1) DEFAULT 1, last_login_at DATETIME NULL, created_at DATETIME);
CREATE TABLE remember_tokens (selector CHAR(12) PRIMARY KEY, validator_hash CHAR(64), user_id INT UNSIGNED, expires_at DATETIME);
CREATE TABLE login_attempts (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, email VARCHAR(120), ip VARCHAR(45), attempted_at DATETIME, KEY (email, attempted_at));
CREATE TABLE audit_log (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED, action VARCHAR(30), entity VARCHAR(30), entity_id INT UNSIGNED, before_json TEXT NULL, after_json TEXT NULL, created_at DATETIME, KEY (entity, entity_id));  -- every create/edit/delete of employees, time_off, adjustments, events, users; feeds the History screen.
CREATE TABLE settings (setting_key VARCHAR(50) PRIMARY KEY, value TEXT);  -- api_key for the JSON endpoint, staff_can_see_all_balances, strict_mirror, last_sync_ok_at.
CREATE TABLE schema_migrations (version VARCHAR(20) PRIMARY KEY, applied_at DATETIME);
